import { z } from 'zod';
import { UlidSchema, RefSchema, DateTimeSchema } from './common.js';

// =============================================================================
// AGENTS
// =============================================================================

/**
 * Standard agent capabilities
 */
export const AgentCapabilitySchema = z.enum([
  'code',
  'test',
  'review',
  'refactor',
  'design',
  'document',
]);

/**
 * Session protocol for agent lifecycle commands
 */
export const SessionProtocolSchema = z.object({
  start: z.string(),
  checkpoint: z.string().optional(),
  end: z.string().optional(),
});

/**
 * Agent definition - describes who works on the project
 */
export const AgentSchema = z.object({
  _ulid: UlidSchema,
  id: z.string().min(1, 'Agent ID is required'),
  name: z.string().min(1, 'Agent name is required'),
  description: z.string().optional(),
  capabilities: z.array(AgentCapabilitySchema).default([]),
  tools: z.array(z.string()).default([]),
  session_protocol: SessionProtocolSchema.optional(),
  conventions: z.array(z.string()).default([]),
});

// =============================================================================
// WORKFLOWS
// =============================================================================

/**
 * Workflow trigger types
 */
export const WorkflowTriggerSchema = z.enum([
  'session-start',
  'task-start',
  'task-complete',
  'behavior-change',
  'spec-update',
  'manual',
]);

/**
 * Workflow step types
 */
export const WorkflowStepTypeSchema = z.enum(['check', 'action', 'decision']);

/**
 * Individual workflow step
 */
export const WorkflowStepSchema = z.object({
  type: WorkflowStepTypeSchema,
  content: z.string().min(1, 'Step content is required'),
  on_fail: z.string().optional(), // For check steps
  options: z.array(z.string()).optional(), // For decision steps
  mode: z.enum(['prompt', 'silent', 'skip']).optional(), // Execution hints
});

/**
 * Workflow definition - describes how work is done
 */
export const WorkflowSchema = z.object({
  _ulid: UlidSchema,
  id: z.string().min(1, 'Workflow ID is required'),
  trigger: WorkflowTriggerSchema,
  description: z.string().optional(),
  steps: z.array(WorkflowStepSchema).default([]),
});

// =============================================================================
// CONVENTIONS
// =============================================================================

/**
 * Convention validation types
 */
export const ConventionValidationTypeSchema = z.enum([
  'regex',
  'enum',
  'range',
  'prose',
]);

/**
 * Convention validation rule
 */
export const ConventionValidationSchema = z.object({
  type: ConventionValidationTypeSchema,
  pattern: z.string().optional(), // For regex
  values: z.array(z.string()).optional(), // For enum
  min: z.number().optional(), // For range
  max: z.number().optional(), // For range
});

/**
 * Convention example
 */
export const ConventionExampleSchema = z.object({
  good: z.string().optional(),
  bad: z.string().optional(),
});

/**
 * Convention definition - describes project standards
 */
export const ConventionSchema = z.object({
  _ulid: UlidSchema,
  domain: z.string().min(1, 'Convention domain is required'),
  rules: z.array(z.string()).default([]),
  validation: ConventionValidationSchema.optional(),
  examples: z.array(ConventionExampleSchema).default([]),
});

// =============================================================================
// OBSERVATIONS
// =============================================================================

/**
 * Observation types for capturing feedback
 */
export const ObservationTypeSchema = z.enum(['friction', 'success', 'question', 'idea']);

/**
 * Observation definition - feedback for process improvement
 */
export const ObservationSchema = z.object({
  _ulid: UlidSchema,
  type: ObservationTypeSchema,
  content: z.string().min(1, 'Observation content is required'),
  context: z.string().optional(),
  created_at: DateTimeSchema,
  author: z.string().optional(),
  tags: z.array(z.string()).default([]),
  workflow_ref: RefSchema.optional(), // Workflow reference if specified
  promoted_to: RefSchema.optional(), // Task reference if promoted
  resolved: z.boolean().default(false),
  resolved_at: DateTimeSchema.optional(),
  resolved_by: z.string().optional(),
  resolution: z.string().optional(),
});

/**
 * Observation input schema (for creating new observations)
 */
export const ObservationInputSchema = ObservationSchema.omit({
  _ulid: true,
  created_at: true,
}).extend({
  _ulid: UlidSchema.optional(),
  created_at: DateTimeSchema.optional(),
});

// =============================================================================
// SESSION CONTEXT
// =============================================================================

/**
 * Session focus - what the agent is currently working on
 */
export const SessionFocusSchema = z.object({
  task: RefSchema.optional(),
  description: z.string().optional(),
});

/**
 * Active thread - ongoing work or investigation
 */
export const SessionThreadSchema = z.object({
  id: z.string(),
  description: z.string(),
  started_at: DateTimeSchema,
  context: z.string().optional(),
});

/**
 * Open question - unresolved inquiry
 */
export const SessionQuestionSchema = z.object({
  id: z.string(),
  question: z.string(),
  context: z.string().optional(),
  asked_at: DateTimeSchema,
});

/**
 * Session context - ephemeral state during work session
 */
export const SessionContextSchema = z.object({
  focus: SessionFocusSchema.optional(),
  threads: z.array(SessionThreadSchema).default([]),
  open_questions: z.array(SessionQuestionSchema).default([]),
  updated_at: DateTimeSchema,
});

// =============================================================================
// META MANIFEST
// =============================================================================

/**
 * Meta manifest schema - root file for process definitions
 */
export const MetaManifestSchema = z.object({
  kynetic_meta: z.string().default('1.0'),
  agents: z.array(AgentSchema).default([]),
  workflows: z.array(WorkflowSchema).default([]),
  conventions: z.array(ConventionSchema).default([]),
  observations: z.array(ObservationSchema).default([]),
  includes: z.array(z.string()).optional(), // External meta files
});

// =============================================================================
// TYPE EXPORTS
// =============================================================================

export type AgentCapability = z.infer<typeof AgentCapabilitySchema>;
export type SessionProtocol = z.infer<typeof SessionProtocolSchema>;
export type Agent = z.infer<typeof AgentSchema>;

export type WorkflowTrigger = z.infer<typeof WorkflowTriggerSchema>;
export type WorkflowStepType = z.infer<typeof WorkflowStepTypeSchema>;
export type WorkflowStep = z.infer<typeof WorkflowStepSchema>;
export type Workflow = z.infer<typeof WorkflowSchema>;

export type ConventionValidationType = z.infer<typeof ConventionValidationTypeSchema>;
export type ConventionValidation = z.infer<typeof ConventionValidationSchema>;
export type ConventionExample = z.infer<typeof ConventionExampleSchema>;
export type Convention = z.infer<typeof ConventionSchema>;

export type ObservationType = z.infer<typeof ObservationTypeSchema>;
export type Observation = z.infer<typeof ObservationSchema>;
export type ObservationInput = z.infer<typeof ObservationInputSchema>;

export type SessionFocus = z.infer<typeof SessionFocusSchema>;
export type SessionThread = z.infer<typeof SessionThreadSchema>;
export type SessionQuestion = z.infer<typeof SessionQuestionSchema>;
export type SessionContext = z.infer<typeof SessionContextSchema>;

export type MetaManifest = z.infer<typeof MetaManifestSchema>;

import { Command } from 'commander';
import chalk from 'chalk';
import { initContext, loadMetaManifest, saveMetaManifest } from '../../parser/index.js';
import { output, error, success } from '../output.js';
import { ulid } from 'ulid';
import { Observation, ObservationType } from '../../schema/meta.js';

/**
 * Format meta manifest summary for display
 */
function formatMetaShow(manifest: NonNullable<Awaited<ReturnType<typeof loadMetaManifest>>>): void {
  console.log(chalk.bold('Meta Manifest Summary'));
  console.log(chalk.gray('─'.repeat(40)));
  console.log(`Agents:       ${manifest.agents.length}`);
  console.log(`Workflows:    ${manifest.workflows.length}`);
  console.log(`Conventions:  ${manifest.conventions.length}`);
  console.log(`Observations: ${manifest.observations.length}`);

  if (manifest.agents.length > 0) {
    console.log(chalk.gray('\nAgents:'));
    for (const agent of manifest.agents) {
      console.log(`  • ${agent.name} (${agent.id})`);
      if (agent.capabilities.length > 0) {
        console.log(chalk.gray(`    ${agent.capabilities.join(', ')}`));
      }
    }
  }

  if (manifest.workflows.length > 0) {
    console.log(chalk.gray('\nWorkflows:'));
    for (const workflow of manifest.workflows) {
      console.log(`  • ${workflow.id} (${workflow.trigger})`);
      if (workflow.description) {
        const desc = workflow.description.split('\n')[0];
        console.log(chalk.gray(`    ${desc}`));
      }
    }
  }

  if (manifest.conventions.length > 0) {
    console.log(chalk.gray('\nConventions:'));
    for (const convention of manifest.conventions) {
      console.log(`  • ${convention.domain}`);
      if (convention.rules.length > 0) {
        console.log(chalk.gray(`    ${convention.rules.length} rule(s)`));
      }
    }
  }

  if (manifest.observations.length > 0) {
    console.log(chalk.gray('\nRecent Observations:'));
    const recent = manifest.observations.slice(-5);
    for (const obs of recent) {
      console.log(`  • [${obs.type}] ${obs.content.split('\n')[0]}`);
      if (obs.promoted_to) {
        console.log(chalk.gray(`    → Promoted to ${obs.promoted_to}`));
      }
    }
    if (manifest.observations.length > 5) {
      console.log(chalk.gray(`  ... and ${manifest.observations.length - 5} more`));
    }
  }
}

/**
 * Format agents table for display
 */
function formatAgentsTable(agents: NonNullable<Awaited<ReturnType<typeof loadMetaManifest>>>['agents']): void {
  if (agents.length === 0) {
    console.log('No agents defined');
    return;
  }

  // Calculate column widths
  const idWidth = Math.max(2, ...agents.map((a) => a.id.length));
  const nameWidth = Math.max(4, ...agents.map((a) => a.name.length));

  // Header
  console.log(
    chalk.bold('ID'.padEnd(idWidth)) +
      '  ' +
      chalk.bold('Name'.padEnd(nameWidth)) +
      '  ' +
      chalk.bold('Capabilities')
  );
  console.log(chalk.gray('─'.repeat(idWidth + nameWidth + 40)));

  // Rows
  for (const agent of agents) {
    const capabilities = agent.capabilities.join(', ') || '-';
    console.log(agent.id.padEnd(idWidth) + '  ' + agent.name.padEnd(nameWidth) + '  ' + capabilities);
  }
}

/**
 * Format workflows table for display
 */
function formatWorkflowsTable(
  workflows: NonNullable<Awaited<ReturnType<typeof loadMetaManifest>>>['workflows']
): void {
  if (workflows.length === 0) {
    console.log('No workflows defined');
    return;
  }

  // Calculate column widths
  const idWidth = Math.max(2, ...workflows.map((w) => w.id.length));
  const triggerWidth = Math.max(7, ...workflows.map((w) => w.trigger.length));

  // Header
  console.log(
    chalk.bold('ID'.padEnd(idWidth)) +
      '  ' +
      chalk.bold('Trigger'.padEnd(triggerWidth)) +
      '  ' +
      chalk.bold('Steps')
  );
  console.log(chalk.gray('─'.repeat(idWidth + triggerWidth + 20)));

  // Rows
  for (const workflow of workflows) {
    const steps = workflow.steps.length.toString();
    console.log(workflow.id.padEnd(idWidth) + '  ' + workflow.trigger.padEnd(triggerWidth) + '  ' + steps);
  }
}

/**
 * Format workflows verbose for display
 */
function formatWorkflowsVerbose(
  workflows: NonNullable<Awaited<ReturnType<typeof loadMetaManifest>>>['workflows']
): void {
  if (workflows.length === 0) {
    console.log('No workflows defined');
    return;
  }

  for (let i = 0; i < workflows.length; i++) {
    const workflow = workflows[i];

    if (i > 0) {
      console.log(''); // Blank line between workflows
    }

    console.log(chalk.bold(workflow.id));
    console.log(chalk.gray(`Trigger: ${workflow.trigger}`));

    if (workflow.description) {
      const desc = workflow.description.trim();
      console.log(chalk.gray(desc.split('\n')[0]));
    }

    console.log(chalk.gray('\nSteps:'));
    for (let j = 0; j < workflow.steps.length; j++) {
      const step = workflow.steps[j];
      const prefix = step.type === 'check' ? '[check]' : step.type === 'action' ? '[action]' : '[decision]';

      console.log(`  ${j + 1}. ${prefix} ${step.content}`);

      if (step.on_fail) {
        console.log(chalk.gray(`     on_fail: ${step.on_fail}`));
      }
    }
  }
}

/**
 * Format observations table for display
 */
function formatObservationsTable(
  observations: NonNullable<Awaited<ReturnType<typeof loadMetaManifest>>>['observations']
): void {
  if (observations.length === 0) {
    console.log('No observations found');
    return;
  }

  // Calculate column widths
  const idWidth = 8; // ULID prefix
  const typeWidth = Math.max(4, ...observations.map((o) => o.type.length));
  const workflowWidth = Math.max(8, ...observations.map((o) => o.workflow_ref?.length || 0));
  const contentWidth = 50;

  // Header
  console.log(
    chalk.bold('ID'.padEnd(idWidth)) +
      '  ' +
      chalk.bold('Type'.padEnd(typeWidth)) +
      '  ' +
      chalk.bold('Workflow'.padEnd(workflowWidth)) +
      '  ' +
      chalk.bold('Created'.padEnd(10)) +
      '  ' +
      chalk.bold('Content')
  );
  console.log(chalk.gray('─'.repeat(idWidth + typeWidth + workflowWidth + contentWidth + 20)));

  // Rows
  for (const obs of observations) {
    const id = obs._ulid.substring(0, 8);
    const workflow = obs.workflow_ref || '-';
    const created = new Date(obs.created_at).toISOString().split('T')[0];
    const content = obs.content.length > contentWidth ? obs.content.substring(0, contentWidth - 3) + '...' : obs.content;

    console.log(
      id.padEnd(idWidth) +
        '  ' +
        obs.type.padEnd(typeWidth) +
        '  ' +
        workflow.padEnd(workflowWidth) +
        '  ' +
        created.padEnd(10) +
        '  ' +
        content
    );
  }
}

/**
 * Register meta commands
 */
export function registerMetaCommand(program: Command): void {
  const meta = program
    .command('meta')
    .description('Manage meta-spec (agents, workflows, conventions, observations)');

  // kspec meta show
  meta
    .command('show')
    .description('Show meta manifest summary')
    .option('--json', 'Output as JSON')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        output(manifest, () => formatMetaShow(manifest));
      } catch (err) {
        error('Failed to load meta manifest', err);
        process.exit(1);
      }
    });

  // kspec meta agents
  meta
    .command('agents')
    .description('List agents defined in meta manifest')
    .option('--json', 'Output as JSON')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        output(manifest.agents, () => formatAgentsTable(manifest.agents));
      } catch (err) {
        error('Failed to load meta manifest', err);
        process.exit(1);
      }
    });

  // kspec meta workflows
  meta
    .command('workflows')
    .description('List workflows defined in meta manifest')
    .option('--json', 'Output as JSON')
    .option('--verbose', 'Show full workflow details with steps')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        if (options.verbose && !options.json) {
          formatWorkflowsVerbose(manifest.workflows);
        } else {
          output(manifest.workflows, () => formatWorkflowsTable(manifest.workflows));
        }
      } catch (err) {
        error('Failed to load meta manifest', err);
        process.exit(1);
      }
    });

  // kspec meta observe <type> <content>
  meta
    .command('observe <type> <content>')
    .description('Create an observation (friction, success, question, idea)')
    .option('--workflow <ref>', 'Reference to workflow this observation relates to')
    .option('--author <author>', 'Author of the observation (defaults to @claude)')
    .option('--tag <tag...>', 'Tags for the observation')
    .action(async (type: string, content: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Validate observation type
        const validTypes: ObservationType[] = ['friction', 'success', 'question', 'idea'];
        if (!validTypes.includes(type as ObservationType)) {
          error(`Invalid observation type: ${type}`);
          console.log(`Valid types: ${validTypes.join(', ')}`);
          process.exit(1);
        }

        // Create observation
        const observation: Observation = {
          _ulid: ulid(),
          type: type as ObservationType,
          content,
          created_at: new Date().toISOString(),
          author: options.author || '@claude',
          tags: options.tag || [],
          workflow_ref: options.workflow,
          resolved: false,
        };

        // Add to manifest
        manifest.observations.push(observation);

        // Save
        await saveMetaManifest(ctx, manifest);

        success(`Created observation: ${observation._ulid.substring(0, 8)}`);
      } catch (err) {
        error('Failed to create observation', err);
        process.exit(1);
      }
    });

  // kspec meta observations
  meta
    .command('observations')
    .description('List observations')
    .option('--json', 'Output as JSON')
    .option('--all', 'Include resolved observations (default: unresolved only)')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Filter observations
        let observations = manifest.observations;
        if (!options.all) {
          observations = observations.filter((obs) => !obs.resolved);
        }

        output(observations, () => formatObservationsTable(observations));
      } catch (err) {
        error('Failed to load observations', err);
        process.exit(1);
      }
    });

  // kspec meta promote <ref>
  meta
    .command('promote <ref>')
    .description('Promote observation to a task')
    .requiredOption('--title <title>', 'Task title')
    .option('--priority <priority>', 'Task priority', '2')
    .option('--force', 'Force promotion even if observation is resolved')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Find observation
        const observation = manifest.observations.find((obs) => obs._ulid.startsWith(ref.replace('@', '')));

        if (!observation) {
          error(`Observation not found: ${ref}`);
          process.exit(1);
        }

        // Check if already promoted
        if (observation.promoted_to) {
          error(`Observation already promoted to task ${observation.promoted_to}; resolve or delete the task first`);
          process.exit(1);
        }

        // Check if resolved
        if (observation.resolved && !options.force) {
          error(`Cannot promote resolved observation; use --force to override`);
          process.exit(1);
        }

        // Create task
        const { spawn } = await import('child_process');
        const { promisify } = await import('util');
        const execFile = promisify(spawn);

        // Build task add command
        const taskArgs = [
          'run',
          'dev',
          '--',
          'task',
          'add',
          '--title',
          options.title,
          '--priority',
          options.priority,
        ];

        if (observation.workflow_ref) {
          taskArgs.push('--meta-ref', observation.workflow_ref);
        }

        // Add tags
        for (const tag of observation.tags) {
          taskArgs.push('--tag', tag);
        }

        // Execute task add command
        const result = await new Promise<{ taskRef: string }>((resolve, reject) => {
          const proc = spawn('npm', taskArgs, {
            cwd: ctx.rootDir,
            stdio: ['inherit', 'pipe', 'inherit'],
          });

          let output = '';
          proc.stdout?.on('data', (data) => {
            output += data.toString();
          });

          proc.on('close', (code) => {
            if (code !== 0) {
              reject(new Error(`Failed to create task (exit code ${code})`));
            } else {
              // Extract task ref from output (format: "OK Created task: 01KF...")
              const match = output.match(/Created task: (@?[A-Z0-9]+)/);
              if (match) {
                resolve({ taskRef: match[1] });
              } else {
                reject(new Error('Could not parse task ref from output'));
              }
            }
          });
        });

        // Update observation with promoted_to (ensure @ prefix)
        observation.promoted_to = result.taskRef.startsWith('@') ? result.taskRef : `@${result.taskRef}`;

        // Add observation content as task description
        await saveMetaManifest(ctx, manifest);

        success(`Created task: ${result.taskRef.substring(0, 8)}`);
      } catch (err) {
        error('Failed to promote observation', err);
        process.exit(1);
      }
    });

  // kspec meta conventions
  meta
    .command('conventions')
    .description('List conventions defined in meta manifest')
    .option('--json', 'Output as JSON')
    .option('--domain <domain>', 'Filter by domain')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Filter by domain if specified
        let conventions = manifest.conventions;
        if (options.domain) {
          conventions = conventions.filter((c) => c.domain === options.domain);
        }

        if (options.domain && !options.json) {
          // Show full details for single domain
          if (conventions.length === 0) {
            console.log(`No convention found for domain: ${options.domain}`);
            process.exit(0);
          }

          const convention = conventions[0];
          console.log(chalk.bold(convention.domain));
          console.log(chalk.gray('─'.repeat(40)));

          console.log(chalk.gray('\nRules:'));
          for (const rule of convention.rules) {
            console.log(`  • ${rule}`);
          }

          if (convention.examples && convention.examples.length > 0) {
            console.log(chalk.gray('\nExamples:'));
            for (const example of convention.examples) {
              console.log(`  ${chalk.green('✓')} ${example.good}`);
              console.log(`  ${chalk.red('✗')} ${example.bad}`);
            }
          }

          if (convention.validation) {
            console.log(chalk.gray('\nValidation:'));
            console.log(`  Type: ${convention.validation.type}`);
            if (convention.validation.type === 'regex' && 'pattern' in convention.validation) {
              console.log(`  Pattern: ${convention.validation.pattern}`);
            }
          }
        } else {
          output(conventions, () => {
            if (conventions.length === 0) {
              console.log('No conventions defined');
              return;
            }

            // Calculate column widths
            const domainWidth = Math.max(6, ...conventions.map((c) => c.domain.length));

            // Header
            console.log(
              chalk.bold('Domain'.padEnd(domainWidth)) +
                '  ' +
                chalk.bold('Rules'.padEnd(5)) +
                '  ' +
                chalk.bold('Validation')
            );
            console.log(chalk.gray('─'.repeat(domainWidth + 30)));

            // Rows
            for (const convention of conventions) {
              const rules = convention.rules.length.toString();
              const validation = convention.validation ? 'yes' : 'no';
              console.log(convention.domain.padEnd(domainWidth) + '  ' + rules.padEnd(5) + '  ' + validation);
            }
          });
        }
      } catch (err) {
        error('Failed to load conventions', err);
        process.exit(1);
      }
    });

  // kspec meta list
  meta
    .command('list')
    .description('List all meta items')
    .option('--json', 'Output as JSON')
    .option('--type <type>', 'Filter by type (agent, workflow, convention, observation)')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Build list of all items with type
        interface MetaListItem {
          type: 'agent' | 'workflow' | 'convention' | 'observation';
          id: string;
          title: string;
          ulid: string;
        }

        const items: MetaListItem[] = [];

        // Add agents
        if (!options.type || options.type === 'agent') {
          for (const agent of manifest.agents) {
            items.push({
              type: 'agent',
              id: agent.id,
              title: agent.name,
              ulid: agent._ulid,
            });
          }
        }

        // Add workflows
        if (!options.type || options.type === 'workflow') {
          for (const workflow of manifest.workflows) {
            items.push({
              type: 'workflow',
              id: workflow.id,
              title: workflow.trigger,
              ulid: workflow._ulid,
            });
          }
        }

        // Add conventions
        if (!options.type || options.type === 'convention') {
          for (const convention of manifest.conventions) {
            items.push({
              type: 'convention',
              id: convention.domain,
              title: `${convention.rules.length} rules`,
              ulid: convention._ulid,
            });
          }
        }

        // Add observations
        if (!options.type || options.type === 'observation') {
          // Only show unresolved by default
          const observations = manifest.observations.filter((o) => !o.resolved);
          for (const observation of observations) {
            items.push({
              type: 'observation',
              id: observation._ulid.substring(0, 8),
              title: observation.content.substring(0, 50) + (observation.content.length > 50 ? '...' : ''),
              ulid: observation._ulid,
            });
          }
        }

        output(items, () => {
          if (items.length === 0) {
            console.log('No meta items found');
            return;
          }

          // Calculate column widths
          const typeWidth = Math.max(4, ...items.map((i) => i.type.length));
          const idWidth = Math.max(2, ...items.map((i) => i.id.length));

          // Header
          console.log(
            chalk.bold('Type'.padEnd(typeWidth)) +
              '  ' +
              chalk.bold('ID'.padEnd(idWidth)) +
              '  ' +
              chalk.bold('Title')
          );
          console.log(chalk.gray('─'.repeat(typeWidth + idWidth + 50)));

          // Rows
          for (const item of items) {
            console.log(item.type.padEnd(typeWidth) + '  ' + item.id.padEnd(idWidth) + '  ' + item.title);
          }
        });
      } catch (err) {
        error('Failed to list meta items', err);
        process.exit(1);
      }
    });

  // kspec meta get <ref>
  meta
    .command('get <ref>')
    .description('Get a meta item by reference')
    .option('--json', 'Output as JSON')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        const refWithoutAt = ref.replace('@', '');

        // Try to find in agents
        const agent = manifest.agents.find((a) => a.id === refWithoutAt || a._ulid.startsWith(refWithoutAt));
        if (agent) {
          output(agent, () => {
            console.log(chalk.bold(agent.name));
            console.log(chalk.gray('─'.repeat(40)));
            console.log(`ID:           ${agent.id}`);
            console.log(`ULID:         ${agent._ulid}`);
            console.log(`Capabilities: ${agent.capabilities.join(', ')}`);

            if (agent.description) {
              console.log(chalk.gray('\nDescription:'));
              console.log(agent.description.trim());
            }

            if (agent.tools && agent.tools.length > 0) {
              console.log(chalk.gray('\nTools:'));
              for (const tool of agent.tools) {
                console.log(`  • ${tool}`);
              }
            }

            if (agent.session_protocol) {
              console.log(chalk.gray('\nSession Protocol:'));
              if (agent.session_protocol.start) {
                console.log(`  Start:      ${agent.session_protocol.start}`);
              }
              if (agent.session_protocol.checkpoint) {
                console.log(`  Checkpoint: ${agent.session_protocol.checkpoint}`);
              }
              if (agent.session_protocol.end) {
                console.log(`  End:        ${agent.session_protocol.end}`);
              }
            }

            if (agent.conventions && agent.conventions.length > 0) {
              console.log(chalk.gray('\nConventions:'));
              for (const conv of agent.conventions) {
                console.log(`  • ${conv}`);
              }
            }
          });
          return;
        }

        // Try workflows
        const workflow = manifest.workflows.find((w) => w.id === refWithoutAt || w._ulid.startsWith(refWithoutAt));
        if (workflow) {
          output(workflow, () => {
            console.log(chalk.bold(workflow.id));
            console.log(chalk.gray('─'.repeat(40)));
            console.log(`ULID:    ${workflow._ulid}`);
            console.log(`Trigger: ${workflow.trigger}`);

            if (workflow.description) {
              console.log(chalk.gray('\nDescription:'));
              console.log(workflow.description.trim());
            }

            console.log(chalk.gray('\nSteps:'));
            for (let i = 0; i < workflow.steps.length; i++) {
              const step = workflow.steps[i];
              const prefix =
                step.type === 'check' ? '[check]' : step.type === 'action' ? '[action]' : '[decision]';
              console.log(`  ${i + 1}. ${prefix} ${step.content}`);

              if (step.on_fail) {
                console.log(chalk.gray(`     on_fail: ${step.on_fail}`));
              }
            }
          });
          return;
        }

        // Try conventions
        const convention = manifest.conventions.find((c) => c.domain === refWithoutAt || c._ulid.startsWith(refWithoutAt));
        if (convention) {
          output(convention, () => {
            console.log(chalk.bold(convention.domain));
            console.log(chalk.gray('─'.repeat(40)));
            console.log(`ULID: ${convention._ulid}`);

            console.log(chalk.gray('\nRules:'));
            for (const rule of convention.rules) {
              console.log(`  • ${rule}`);
            }

            if (convention.examples && convention.examples.length > 0) {
              console.log(chalk.gray('\nExamples:'));
              for (const example of convention.examples) {
                console.log(`  ${chalk.green('✓')} ${example.good}`);
                console.log(`  ${chalk.red('✗')} ${example.bad}`);
              }
            }

            if (convention.validation) {
              console.log(chalk.gray('\nValidation:'));
              console.log(`  Type: ${convention.validation.type}`);
              if (convention.validation.type === 'regex' && 'pattern' in convention.validation) {
                console.log(`  Pattern: ${convention.validation.pattern}`);
              }
            }
          });
          return;
        }

        // Try observations
        const observation = manifest.observations.find((o) => o._ulid.startsWith(refWithoutAt));
        if (observation) {
          output(observation, () => {
            console.log(chalk.bold(`Observation (${observation.type})`));
            console.log(chalk.gray('─'.repeat(40)));
            console.log(`ULID:         ${observation._ulid}`);
            console.log(`Type:         ${observation.type}`);
            console.log(`Created:      ${observation.created_at}`);
            console.log(`Author:       ${observation.author}`);
            console.log(`Resolved:     ${observation.resolved ? 'yes' : 'no'}`);

            if (observation.workflow_ref) {
              console.log(`Workflow Ref: ${observation.workflow_ref}`);
            }

            if (observation.tags.length > 0) {
              console.log(`Tags:         ${observation.tags.join(', ')}`);
            }

            if (observation.promoted_to) {
              console.log(`Promoted To:  ${observation.promoted_to}`);
            }

            console.log(chalk.gray('\nContent:'));
            console.log(observation.content.trim());

            if (observation.resolved && observation.resolution) {
              console.log(chalk.gray('\nResolution:'));
              console.log(observation.resolution.trim());
              if (observation.resolved_at) {
                console.log(chalk.gray(`Resolved at: ${observation.resolved_at}`));
              }
              if (observation.resolved_by) {
                console.log(chalk.gray(`Resolved by: ${observation.resolved_by}`));
              }
            }
          });
          return;
        }

        // Not found
        error(`Meta item not found: ${ref}`);
        process.exit(1);
      } catch (err) {
        error('Failed to get meta item', err);
        process.exit(1);
      }
    });

  // kspec meta resolve <ref>
  meta
    .command('resolve <ref>')
    .description('Resolve an observation')
    .argument('[resolution]', 'Resolution text (optional if observation has promoted_to)')
    .action(async (ref: string, resolution: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec manifest found');
          console.log('Run `kspec init` to create a new project');
          process.exit(1);
        }

        const manifest = await loadMetaManifest(ctx);

        if (!manifest) {
          error('No meta manifest found (kynetic.meta.yaml)');
          console.log('The meta manifest defines agents, workflows, and conventions for the project.');
          process.exit(1);
        }

        // Find observation
        const observation = manifest.observations.find((obs) => obs._ulid.startsWith(ref.replace('@', '')));

        if (!observation) {
          error(`Observation not found: ${ref}`);
          process.exit(1);
        }

        // Check if already resolved
        if (observation.resolved) {
          const truncated = observation.resolution?.substring(0, 50) || '';
          const suffix = observation.resolution && observation.resolution.length > 50 ? '...' : '';
          error(
            `Observation already resolved on ${observation.resolved_at}: '${truncated}${suffix}'`
          );
          process.exit(1);
        }

        // Handle resolution text
        let resolutionText = resolution;

        // If no resolution provided and observation was promoted, try to get from task
        if (!resolutionText && observation.promoted_to) {
          // TODO: Load task and get completion reason
          // For now, require explicit resolution
          error('Resolution text required (auto-populate from task not yet implemented)');
          process.exit(1);
        }

        if (!resolutionText) {
          error('Resolution text required');
          process.exit(1);
        }

        // Update observation
        observation.resolved = true;
        observation.resolved_at = new Date().toISOString();
        observation.resolved_by = '@claude'; // TODO: Get from context
        observation.resolution = resolutionText;

        // Save
        await saveMetaManifest(ctx, manifest);

        success(`Resolved: ${observation._ulid.substring(0, 8)}`);
      } catch (err) {
        error('Failed to resolve observation', err);
        process.exit(1);
      }
    });
}

