export async function loadMetaManifest(ctx: KspecContext): Promise<MetaManifest | null> {
  const metaPath = await findMetaManifest(ctx);
  if (!metaPath) {
    return null;
  }

  try {
    const raw = await readYamlFile<unknown>(metaPath);
    return MetaManifestSchema.parse(raw);
  } catch (err) {
    if (err instanceof z.ZodError) {
      throw new Error(`Invalid meta manifest schema: ${err.message}`);
    }
    throw err;
  }
}

/**
 * Save meta manifest to file
 * Creates kynetic.meta.yaml in the spec directory
 */
export async function saveMetaManifest(
  ctx: KspecContext,
  manifest: MetaManifest
): Promise<void> {
  if (!ctx.specDir) {
    throw new Error('Cannot save meta manifest: spec directory not found');
  }

  // Validate before saving
  MetaManifestSchema.parse(manifest);

  const metaPath = path.join(ctx.specDir, 'kynetic.meta.yaml');
  await writeYamlFile(metaPath, manifest);

  // Auto-commit if shadow mode is enabled
  if (ctx.shadow?.enabled) {
    await shadowAutoCommit(ctx.specDir, `chore: update meta manifest`);
  }
}

