    const manifest = parsed.data;
    const index = manifest.observations.findIndex((o) => o._ulid === ulid);
    if (index < 0) {
      return false;
    }

    manifest.observations.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

