/**
 * Meta CLI commands for interacting with meta-spec.
 *
 * Commands:
 * - kspec meta show: Display meta-spec summary
 * - kspec meta agents: List defined agents
 * - kspec meta workflows: List defined workflows
 * - kspec meta conventions: List defined conventions
 * - kspec meta observe: Create an observation
 * - kspec meta observations: List observations
 * - kspec meta promote: Promote observation to task
 * - kspec meta resolve: Resolve an observation
 */

import { Command } from 'commander';
import chalk from 'chalk';
import * as readline from 'node:readline';
import { ulid } from 'ulid';
import yaml from 'js-yaml';
import {
  initContext,
  loadMetaContext,
  getMetaStats,
  findMetaItemByRef,
  createObservation,
  saveObservation,
  createTask,
  saveTask,
  loadAllTasks,
  loadAllItems,
  ReferenceIndex,
  saveMetaItem,
  deleteMetaItem,
  getSessionContextPath,
  loadSessionContext,
  saveSessionContext,
  type MetaContext,
  type LoadedObservation,
  type LoadedAgent,
  type LoadedWorkflow,
  type LoadedConvention,
  type LoadedMetaItem,
  type SessionContext,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import type { TaskInput, ObservationType } from '../../schema/index.js';
import { output, success, error, info, isJsonMode } from '../output.js';

/**
 * Format meta show output
 */
function formatMetaShow(meta: MetaContext): void {
  const stats = getMetaStats(meta);

  if (!meta.manifest) {
    console.log(chalk.yellow('No meta manifest found (kynetic.meta.yaml)'));
    console.log(chalk.gray('Run `kspec init --meta` to create one'));
    return;
  }

  console.log(chalk.bold('Meta-Spec Summary'));
  console.log(chalk.gray('─'.repeat(40)));
  console.log(`Agents:       ${stats.agents}`);
  console.log(`Workflows:    ${stats.workflows}`);
  console.log(`Conventions:  ${stats.conventions}`);
  console.log(`Observations: ${stats.observations} (${stats.unresolvedObservations} unresolved)`);
}

/**
 * Format agents table output
 */
function formatAgentsTable(meta: MetaContext): void {
  if (meta.agents.length === 0) {
    console.log(chalk.gray('No agents defined'));
    return;
  }

  console.log(chalk.bold('Agents'));
  console.log(chalk.gray('─'.repeat(60)));

  for (const agent of meta.agents) {
    const caps = agent.capabilities.join(', ') || chalk.gray('none');
    console.log(`${chalk.cyan(agent.id.padEnd(15))} ${agent.name.padEnd(30)} ${caps}`);
  }

  console.log(chalk.gray(`\n${meta.agents.length} agent(s)`));
}

/**
 * Format workflows table output
 */
function formatWorkflowsTable(meta: MetaContext, verbose: boolean): void {
  if (meta.workflows.length === 0) {
    console.log(chalk.gray('No workflows defined'));
    return;
  }

  console.log(chalk.bold('Workflows'));
  console.log(chalk.gray('─'.repeat(60)));

  for (const workflow of meta.workflows) {
    const stepCount = workflow.steps.length;
    console.log(`${chalk.cyan(workflow.id.padEnd(20))} ${workflow.trigger.padEnd(25)} ${stepCount} step(s)`);

    if (verbose && workflow.steps.length > 0) {
      for (const step of workflow.steps) {
        const typePrefix = {
          check: chalk.yellow('[check]'),
          action: chalk.blue('[action]'),
          decision: chalk.magenta('[decision]'),
        }[step.type];

        console.log(`  ${typePrefix} ${step.content}`);
        if (step.on_fail) {
          console.log(chalk.gray(`    on_fail: ${step.on_fail}`));
        }
      }
      console.log('');
    }
  }

  console.log(chalk.gray(`\n${meta.workflows.length} workflow(s)`));
}

/**
 * Format conventions table output
 */
function formatConventionsTable(meta: MetaContext, domain?: string): void {
  let conventions = meta.conventions;

  if (domain) {
    conventions = conventions.filter((c) => c.domain === domain);
  }

  if (conventions.length === 0) {
    if (domain) {
      console.log(chalk.gray(`No convention found for domain: ${domain}`));
    } else {
      console.log(chalk.gray('No conventions defined'));
    }
    return;
  }

  console.log(chalk.bold('Conventions'));
  console.log(chalk.gray('─'.repeat(60)));

  for (const conv of conventions) {
    const ruleCount = conv.rules.length;
    const hasValidation = conv.validation ? 'yes' : 'no';
    console.log(
      `${chalk.cyan(conv.domain.padEnd(15))} ${ruleCount} rule(s)`.padEnd(35) +
        ` Validation: ${hasValidation}`
    );

    // If filtering by domain, show full details
    if (domain) {
      if (conv.rules.length > 0) {
        console.log(chalk.gray('\nRules:'));
        for (const rule of conv.rules) {
          console.log(chalk.gray(`  - ${rule}`));
        }
      }
      if (conv.examples.length > 0) {
        console.log(chalk.gray('\nExamples:'));
        for (const ex of conv.examples) {
          console.log(chalk.green(`  Good: ${ex.good}`));
          console.log(chalk.red(`  Bad:  ${ex.bad}`));
        }
      }
    }
  }

  if (!domain) {
    console.log(chalk.gray(`\n${conventions.length} convention(s)`));
  }
}

/**
 * Format relative time for display
 */
function formatRelativeTime(dateStr: string): string {
  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return 'just now';
  if (diffMins < 60) return `${diffMins} minute${diffMins === 1 ? '' : 's'} ago`;
  if (diffHours < 24) return `${diffHours} hour${diffHours === 1 ? '' : 's'} ago`;
  if (diffDays < 7) return `${diffDays} day${diffDays === 1 ? '' : 's'} ago`;
  return date.toLocaleDateString();
}

/**
 * Get short ULID for display (first 8 chars)
 */
function shortUlid(ulid: string): string {
  return ulid.slice(0, 8);
}

/**
 * Truncate string for display
 */
function truncate(str: string, maxLen: number): string {
  if (str.length <= maxLen) return str;
  return str.slice(0, maxLen - 3) + '...';
}

/**
 * Simple prompt for user input
 */
async function prompt(question: string): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

/**
 * Find observation by ref with error handling
 */
function findObservationByRef(
  meta: MetaContext,
  ref: string
): LoadedObservation {
  const item = findMetaItemByRef(meta, ref);
  if (!item) {
    error(`Observation not found: ${ref}`);
    process.exit(3);
  }
  if (!('content' in item) || !('resolved' in item)) {
    error(`Reference is not an observation: ${ref}`);
    process.exit(3);
  }
  return item as LoadedObservation;
}

/**
 * Format observations table output
 */
function formatObservationsTable(observations: LoadedObservation[]): void {
  if (observations.length === 0) {
    console.log(chalk.gray('No observations found'));
    return;
  }

  console.log(chalk.bold('Observations'));
  console.log(chalk.gray('─'.repeat(80)));

  // Header
  console.log(
    `${chalk.gray('ID'.padEnd(10))} ` +
    `${chalk.gray('Type'.padEnd(10))} ` +
    `${chalk.gray('Workflow'.padEnd(15))} ` +
    `${chalk.gray('Created'.padEnd(14))} ` +
    `${chalk.gray('Content')}`
  );

  for (const obs of observations) {
    const typeColors: Record<string, (s: string) => string> = {
      friction: chalk.red,
      success: chalk.green,
      question: chalk.yellow,
      idea: chalk.blue,
    };
    const colorFn = typeColors[obs.type] || chalk.white;

    const workflow = obs.workflow_ref ? obs.workflow_ref.slice(0, 13) : '-';
    const created = formatRelativeTime(obs.created_at).padEnd(14);
    const content = truncate(obs.content.replace(/\n/g, ' '), 35);
    const resolved = obs.resolved ? chalk.gray(' [resolved]') : '';

    console.log(
      `${shortUlid(obs._ulid).padEnd(10)} ` +
      `${colorFn(obs.type.padEnd(10))} ` +
      `${workflow.padEnd(15)} ` +
      `${created} ` +
      `${content}${resolved}`
    );
  }

  console.log(chalk.gray(`\n${observations.length} observation(s)`));
}

/**
 * Valid observation types
 */
const OBSERVATION_TYPES = ['friction', 'success', 'question', 'idea'];

/**
 * Valid meta item types for add command
 */
const META_ITEM_TYPES = ['agent', 'workflow', 'convention'];

/**
 * Format a single meta item for display (get command)
 */
function formatMetaItem(item: LoadedMetaItem): void {
  const itemType = getMetaItemType(item);

  switch (itemType) {
    case 'agent': {
      const agent = item as LoadedAgent;
      console.log(chalk.bold(agent.name));
      console.log(chalk.gray('─'.repeat(40)));
      console.log(`ID:           ${chalk.cyan(agent.id)}`);
      console.log(`ULID:         ${agent._ulid}`);
      console.log(`Type:         agent`);
      if (agent.description) {
        console.log(`\n${chalk.gray('Description:')}`);
        console.log(agent.description.trim());
      }
      if (agent.capabilities.length > 0) {
        console.log(`\nCapabilities: ${agent.capabilities.join(', ')}`);
      }
      if (agent.tools.length > 0) {
        console.log(`Tools:        ${agent.tools.join(', ')}`);
      }
      if (agent.session_protocol) {
        console.log(`\n${chalk.gray('Session Protocol:')}`);
        if (agent.session_protocol.start) console.log(`  start:      ${agent.session_protocol.start}`);
        if (agent.session_protocol.checkpoint) console.log(`  checkpoint: ${agent.session_protocol.checkpoint}`);
        if (agent.session_protocol.end) console.log(`  end:        ${agent.session_protocol.end}`);
      }
      if (agent.conventions.length > 0) {
        console.log(`\n${chalk.gray('Conventions:')}`);
        for (const conv of agent.conventions) {
          console.log(`  - ${conv}`);
        }
      }
      break;
    }
    case 'workflow': {
      const workflow = item as LoadedWorkflow;
      console.log(chalk.bold(workflow.id));
      console.log(chalk.gray('─'.repeat(40)));
      console.log(`ULID:    ${workflow._ulid}`);
      console.log(`Type:    workflow`);
      console.log(`Trigger: ${workflow.trigger}`);
      if (workflow.description) {
        console.log(`\n${chalk.gray('Description:')}`);
        console.log(workflow.description.trim());
      }
      if (workflow.steps.length > 0) {
        console.log(`\n${chalk.gray('Steps:')}`);
        for (const step of workflow.steps) {
          const typePrefix = {
            check: chalk.yellow('[check]'),
            action: chalk.blue('[action]'),
            decision: chalk.magenta('[decision]'),
          }[step.type];
          console.log(`  ${typePrefix} ${step.content}`);
          if (step.on_fail) {
            console.log(chalk.gray(`    on_fail: ${step.on_fail}`));
          }
        }
      }
      break;
    }
    case 'convention': {
      const conv = item as LoadedConvention;
      console.log(chalk.bold(conv.domain));
      console.log(chalk.gray('─'.repeat(40)));
      console.log(`ULID: ${conv._ulid}`);
      console.log(`Type: convention`);
      if (conv.rules.length > 0) {
        console.log(`\n${chalk.gray('Rules:')}`);
        for (const rule of conv.rules) {
          console.log(`  - ${rule}`);
        }
      }
      if (conv.examples.length > 0) {
        console.log(`\n${chalk.gray('Examples:')}`);
        for (const ex of conv.examples) {
          console.log(chalk.green(`  Good: ${ex.good}`));
          console.log(chalk.red(`  Bad:  ${ex.bad}`));
        }
      }
      if (conv.validation) {
        console.log(`\n${chalk.gray('Validation:')}`);
        console.log(`  type: ${conv.validation.type}`);
        if (conv.validation.pattern) console.log(`  pattern: ${conv.validation.pattern}`);
      }
      break;
    }
    case 'observation': {
      const obs = item as LoadedObservation;
      console.log(chalk.bold(`Observation: ${obs.type}`));
      console.log(chalk.gray('─'.repeat(40)));
      console.log(`ULID:     ${obs._ulid}`);
      console.log(`Type:     observation (${obs.type})`);
      console.log(`Author:   ${obs.author || 'unknown'}`);
      console.log(`Created:  ${formatRelativeTime(obs.created_at)}`);
      if (obs.workflow_ref) {
        console.log(`Workflow: ${obs.workflow_ref}`);
      }
      console.log(`Resolved: ${obs.resolved ? 'yes' : 'no'}`);
      console.log(`\n${chalk.gray('Content:')}`);
      console.log(obs.content.trim());
      if (obs.resolved && obs.resolution) {
        console.log(`\n${chalk.gray('Resolution:')}`);
        console.log(obs.resolution);
      }
      if (obs.promoted_to) {
        console.log(`\nPromoted to: ${obs.promoted_to}`);
      }
      break;
    }
  }
}

/**
 * Get the meta item type from a loaded item
 */
function getMetaItemType(item: LoadedMetaItem): 'agent' | 'workflow' | 'convention' | 'observation' {
  if ('capabilities' in item) return 'agent';
  if ('trigger' in item) return 'workflow';
  if ('domain' in item) return 'convention';
  return 'observation';
}

/**
 * Format meta list table
 */
function formatMetaListTable(meta: MetaContext, typeFilter?: string): void {
  const items: { type: string; id: string; ulid: string; label: string }[] = [];

  for (const agent of meta.agents) {
    if (!typeFilter || typeFilter === 'agent') {
      items.push({
        type: 'agent',
        id: agent.id,
        ulid: agent._ulid,
        label: agent.name,
      });
    }
  }

  for (const workflow of meta.workflows) {
    if (!typeFilter || typeFilter === 'workflow') {
      items.push({
        type: 'workflow',
        id: workflow.id,
        ulid: workflow._ulid,
        label: workflow.trigger,
      });
    }
  }

  for (const conv of meta.conventions) {
    if (!typeFilter || typeFilter === 'convention') {
      items.push({
        type: 'convention',
        id: conv.domain,
        ulid: conv._ulid,
        label: `${conv.rules.length} rule(s)`,
      });
    }
  }

  for (const obs of meta.observations) {
    if (!typeFilter || typeFilter === 'observation') {
      items.push({
        type: 'observation',
        id: shortUlid(obs._ulid),
        ulid: obs._ulid,
        label: truncate(obs.content, 30),
      });
    }
  }

  if (items.length === 0) {
    console.log(chalk.gray(typeFilter ? `No ${typeFilter}s found` : 'No meta items found'));
    return;
  }

  console.log(chalk.bold('Meta Items'));
  console.log(chalk.gray('─'.repeat(70)));
  console.log(
    `${chalk.gray('Type'.padEnd(12))} ` +
    `${chalk.gray('ID'.padEnd(20))} ` +
    `${chalk.gray('Label')}`
  );

  for (const item of items) {
    const typeColors: Record<string, (s: string) => string> = {
      agent: chalk.cyan,
      workflow: chalk.yellow,
      convention: chalk.green,
      observation: chalk.magenta,
    };
    const colorFn = typeColors[item.type] || chalk.white;
    console.log(
      `${colorFn(item.type.padEnd(12))} ` +
      `${item.id.padEnd(20)} ` +
      `${item.label}`
    );
  }

  console.log(chalk.gray(`\n${items.length} item(s)`));
}

/**
 * Format session context for display
 */
function formatSessionContext(context: SessionContext): void {
  console.log(chalk.bold('Session Context'));
  console.log(chalk.gray('─'.repeat(40)));

  if (context.focus) {
    console.log(`Focus: ${chalk.cyan(context.focus)}`);
  } else {
    console.log(`Focus: ${chalk.gray('(none)')}`);
  }

  if (context.threads.length > 0) {
    console.log(`\n${chalk.gray('Active Threads:')}`);
    for (const thread of context.threads) {
      console.log(`  - ${thread}`);
    }
  }

  if (context.open_questions.length > 0) {
    console.log(`\n${chalk.gray('Open Questions:')}`);
    for (const question of context.open_questions) {
      console.log(`  - ${question}`);
    }
  }

  console.log(`\nLast updated: ${formatRelativeTime(context.updated_at)}`);
}

/**
 * Register meta commands
 */
export function registerMetaCommands(program: Command): void {
  const meta = program
    .command('meta')
    .description('Meta-spec commands (agents, workflows, conventions, observations)');

  // kspec meta show
  meta
    .command('show')
    .description('Display meta-spec summary')
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const stats = getMetaStats(metaCtx);

        output(
          {
            manifest: metaCtx.manifestPath,
            stats,
          },
          () => formatMetaShow(metaCtx)
        );
      } catch (err) {
        error('Failed to show meta', err);
        process.exit(1);
      }
    });

  // kspec meta agents
  meta
    .command('agents')
    .description('List defined agents')
    .option('--capabilities', 'Group by capabilities')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);

        output(
          metaCtx.agents.map((a) => ({
            id: a.id,
            name: a.name,
            description: a.description,
            capabilities: a.capabilities,
            tools: a.tools,
            session_protocol: a.session_protocol,
            conventions: a.conventions,
          })),
          () => formatAgentsTable(metaCtx)
        );
      } catch (err) {
        error('Failed to list agents', err);
        process.exit(1);
      }
    });

  // kspec meta workflows
  meta
    .command('workflows')
    .description('List defined workflows')
    .option('-v, --verbose', 'Show full step list')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);

        output(
          metaCtx.workflows.map((w) => ({
            id: w.id,
            trigger: w.trigger,
            description: w.description,
            steps: w.steps,
          })),
          () => formatWorkflowsTable(metaCtx, options.verbose)
        );
      } catch (err) {
        error('Failed to list workflows', err);
        process.exit(1);
      }
    });

  // kspec meta conventions
  meta
    .command('conventions')
    .description('List defined conventions')
    .option('--domain <domain>', 'Filter by domain')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);

        let conventions = metaCtx.conventions;
        if (options.domain) {
          conventions = conventions.filter((c) => c.domain === options.domain);
        }

        output(
          conventions.map((c) => ({
            domain: c.domain,
            rules: c.rules,
            examples: c.examples,
            validation: c.validation,
          })),
          () => formatConventionsTable(metaCtx, options.domain)
        );
      } catch (err) {
        error('Failed to list conventions', err);
        process.exit(1);
      }
    });

  // kspec meta observe <type> <description>
  meta
    .command('observe <type> <description>')
    .description('Create an observation (friction, success, question, idea)')
    .option('--workflow <ref>', 'Link to a workflow')
    .action(async (type: string, description: string, options) => {
      try {
        // Validate type
        if (!OBSERVATION_TYPES.includes(type)) {
          error(`Invalid observation type: ${type}. Valid types: ${OBSERVATION_TYPES.join(', ')}`);
          process.exit(2);
        }

        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        // Create and save observation
        const obs = createObservation(type as ObservationType, description, {
          workflow_ref: options.workflow,
        });

        await saveObservation(ctx, { ...obs, _sourceFile: undefined });
        await commitIfShadow(ctx.shadow, 'meta-observe', shortUlid(obs._ulid));

        success(`Created observation: ${shortUlid(obs._ulid)}`, { observation: obs });
      } catch (err) {
        error('Failed to create observation', err);
        process.exit(1);
      }
    });

  // kspec meta observations
  meta
    .command('observations')
    .description('List observations')
    .option('--all', 'Include resolved observations')
    .option('--type <type>', 'Filter by type (friction, success, question, idea)')
    .option('--workflow <ref>', 'Filter by workflow reference')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);

        let observations = metaCtx.observations;

        // Filter by resolved status
        if (!options.all) {
          observations = observations.filter((o) => !o.resolved);
        }

        // Filter by type
        if (options.type) {
          if (!OBSERVATION_TYPES.includes(options.type)) {
            error(`Invalid observation type: ${options.type}. Valid types: ${OBSERVATION_TYPES.join(', ')}`);
            process.exit(2);
          }
          observations = observations.filter((o) => o.type === options.type);
        }

        // Filter by workflow
        if (options.workflow) {
          const cleanRef = options.workflow.startsWith('@') ? options.workflow : `@${options.workflow}`;
          observations = observations.filter((o) => o.workflow_ref === cleanRef);
        }

        // Sort by created_at (newest first)
        observations.sort((a, b) =>
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        );

        output(
          observations.map((o) => ({
            _ulid: o._ulid,
            type: o.type,
            content: o.content,
            workflow_ref: o.workflow_ref,
            created_at: o.created_at,
            author: o.author,
            resolved: o.resolved,
            resolution: o.resolution,
            resolved_at: o.resolved_at,
            resolved_by: o.resolved_by,
            promoted_to: o.promoted_to,
          })),
          () => formatObservationsTable(observations)
        );
      } catch (err) {
        error('Failed to list observations', err);
        process.exit(1);
      }
    });

  // kspec meta promote <ref>
  meta
    .command('promote <ref>')
    .description('Promote observation to task')
    .option('--title <title>', 'Task title (prompts if not provided)')
    .option('--priority <n>', 'Task priority (1-5)', '3')
    .option('--tag <tag...>', 'Tags for the task')
    .option('--force', 'Promote even if already resolved')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const obs = findObservationByRef(metaCtx, ref);

        // AC-6: Check if already promoted
        if (obs.promoted_to) {
          error(`Observation already promoted to task ${obs.promoted_to}; resolve or delete the task first`);
          process.exit(1);
        }

        // AC-8: Check if resolved (unless --force)
        if (obs.resolved && !options.force) {
          error('Cannot promote resolved observation; use --force to override');
          process.exit(1);
        }

        // Get title
        let title = options.title;
        if (!title) {
          console.log(`Promoting: "${truncate(obs.content, 60)}"`);
          console.log('');
          title = await prompt('Task title: ');
          if (!title) {
            error('Task title is required');
            process.exit(2);
          }
        }

        // Create the task
        const taskInput: TaskInput = {
          title,
          type: 'task',
          priority: parseInt(options.priority, 10),
          spec_ref: null,
          meta_ref: obs.workflow_ref || null, // Use workflow_ref as meta_ref
          tags: options.tag || [],
          description: obs.content,
        };

        const task = createTask(taskInput);
        await saveTask(ctx, task);

        // Update observation with promoted_to
        obs.promoted_to = `@${shortUlid(task._ulid)}`;
        await saveObservation(ctx, obs);

        // Load index for display
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);

        await commitIfShadow(ctx.shadow, 'meta-promote', shortUlid(task._ulid));

        success(`Created task: ${index.shortUlid(task._ulid)}`, { task, observation: obs });
      } catch (err) {
        error('Failed to promote observation', err);
        process.exit(1);
      }
    });

  // kspec meta resolve <ref> [resolution]
  meta
    .command('resolve <ref> [resolution]')
    .description('Resolve an observation')
    .action(async (ref: string, resolution: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const obs = findObservationByRef(metaCtx, ref);

        // AC-7: Check if already resolved
        if (obs.resolved) {
          const resolvedDate = obs.resolved_at
            ? new Date(obs.resolved_at).toLocaleDateString()
            : 'unknown date';
          const resolutionText = obs.resolution
            ? truncate(obs.resolution, 40)
            : '';
          error(`Observation already resolved on ${resolvedDate}: '${resolutionText}'`);
          process.exit(1);
        }

        // AC-9: If promoted to a task, try to get completion reason
        let finalResolution = resolution;
        if (!finalResolution && obs.promoted_to) {
          // Try to find the task and get its completion reason
          const tasks = await loadAllTasks(ctx);
          const items = await loadAllItems(ctx);
          const index = new ReferenceIndex(tasks, items);
          const resolved = index.resolve(obs.promoted_to);
          const task = resolved.ok ? resolved.item : null;

          if (task && 'status' in task && task.status === 'completed' && 'closed_reason' in task && task.closed_reason) {
            finalResolution = task.closed_reason as string;
            info(`Auto-populated resolution from completed task: ${truncate(finalResolution, 50)}`);
          } else if (!finalResolution) {
            // Prompt for resolution
            finalResolution = await prompt('Resolution: ');
          }
        }

        if (!finalResolution) {
          finalResolution = await prompt('Resolution: ');
        }

        if (!finalResolution) {
          error('Resolution text is required');
          process.exit(2);
        }

        // Update observation
        obs.resolved = true;
        obs.resolution = finalResolution;
        obs.resolved_at = new Date().toISOString();
        obs.resolved_by = obs.author; // Use same author convention

        await saveObservation(ctx, obs);
        await commitIfShadow(ctx.shadow, 'meta-resolve', shortUlid(obs._ulid));

        success(`Resolved: ${shortUlid(obs._ulid)}`, { observation: obs });
      } catch (err) {
        error('Failed to resolve observation', err);
        process.exit(1);
      }
    });

  // kspec meta get <ref>
  meta
    .command('get <ref>')
    .description('Get a meta item by reference')
    .option('--yaml', 'Output as YAML')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const item = findMetaItemByRef(metaCtx, ref);

        if (!item) {
          error(`Meta item not found: ${ref}`);
          process.exit(3);
        }

        // Strip _sourceFile for output
        const { _sourceFile, ...cleanItem } = item as LoadedMetaItem & { _sourceFile?: string };

        if (options.yaml) {
          console.log(yaml.dump(cleanItem));
        } else {
          output(cleanItem, () => formatMetaItem(item));
        }
      } catch (err) {
        error('Failed to get meta item', err);
        process.exit(1);
      }
    });

  // kspec meta list
  meta
    .command('list')
    .description('List all meta items')
    .option('--type <type>', 'Filter by type (agent, workflow, convention, observation)')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);

        // Build unified list for JSON output
        const allItems: Array<{
          type: string;
          id: string;
          _ulid: string;
          name?: string;
          trigger?: string;
          domain?: string;
          content?: string;
        }> = [];

        for (const agent of metaCtx.agents) {
          if (!options.type || options.type === 'agent') {
            allItems.push({
              type: 'agent',
              id: agent.id,
              _ulid: agent._ulid,
              name: agent.name,
            });
          }
        }

        for (const workflow of metaCtx.workflows) {
          if (!options.type || options.type === 'workflow') {
            allItems.push({
              type: 'workflow',
              id: workflow.id,
              _ulid: workflow._ulid,
              trigger: workflow.trigger,
            });
          }
        }

        for (const conv of metaCtx.conventions) {
          if (!options.type || options.type === 'convention') {
            allItems.push({
              type: 'convention',
              id: conv.domain,
              _ulid: conv._ulid,
              domain: conv.domain,
            });
          }
        }

        for (const obs of metaCtx.observations) {
          if (!options.type || options.type === 'observation') {
            allItems.push({
              type: 'observation',
              id: shortUlid(obs._ulid),
              _ulid: obs._ulid,
              content: obs.content,
            });
          }
        }

        output(allItems, () => formatMetaListTable(metaCtx, options.type));
      } catch (err) {
        error('Failed to list meta items', err);
        process.exit(1);
      }
    });

  // kspec meta add <type>
  meta
    .command('add <type>')
    .description('Add a new meta item (agent, workflow, convention)')
    .option('--id <id>', 'Item ID (required for agent/workflow)')
    .option('--name <name>', 'Display name (required for agent)')
    .option('--trigger <trigger>', 'Workflow trigger (required for workflow)')
    .option('--domain <domain>', 'Convention domain (required for convention)')
    .option('--description <description>', 'Description')
    .option('--capabilities <caps>', 'Agent capabilities (comma-separated)')
    .option('--tools <tools>', 'Agent tools (comma-separated)')
    .option('--rules <rules...>', 'Convention rules (repeatable)')
    .action(async (type: string, options) => {
      try {
        if (!META_ITEM_TYPES.includes(type)) {
          error(`Invalid meta item type: ${type}. Valid types: ${META_ITEM_TYPES.join(', ')}`);
          process.exit(2);
        }

        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const newUlid = ulid();

        if (type === 'agent') {
          if (!options.id) {
            error('Agent requires --id');
            process.exit(2);
          }
          if (!options.name) {
            error('Agent requires --name');
            process.exit(2);
          }

          const agent: LoadedAgent = {
            _ulid: newUlid,
            id: options.id,
            name: options.name,
            description: options.description,
            capabilities: options.capabilities ? options.capabilities.split(',').map((c: string) => c.trim()) : [],
            tools: options.tools ? options.tools.split(',').map((t: string) => t.trim()) : [],
            conventions: [],
          };

          await saveMetaItem(ctx, agent, 'agent');
          await commitIfShadow(ctx.shadow, 'meta-add-agent', shortUlid(newUlid));
          success(`Created agent: ${shortUlid(newUlid)}`, { agent });
        } else if (type === 'workflow') {
          if (!options.id) {
            error('Workflow requires --id');
            process.exit(2);
          }
          if (!options.trigger) {
            error('Workflow requires --trigger');
            process.exit(2);
          }

          const workflow: LoadedWorkflow = {
            _ulid: newUlid,
            id: options.id,
            trigger: options.trigger,
            description: options.description,
            steps: [],
          };

          await saveMetaItem(ctx, workflow, 'workflow');
          await commitIfShadow(ctx.shadow, 'meta-add-workflow', shortUlid(newUlid));
          success(`Created workflow: ${shortUlid(newUlid)}`, { workflow });
        } else if (type === 'convention') {
          if (!options.domain) {
            error('Convention requires --domain');
            process.exit(2);
          }

          const convention: LoadedConvention = {
            _ulid: newUlid,
            domain: options.domain,
            rules: options.rules || [],
            examples: [],
          };

          await saveMetaItem(ctx, convention, 'convention');
          await commitIfShadow(ctx.shadow, 'meta-add-convention', shortUlid(newUlid));
          success(`Created convention: ${shortUlid(newUlid)}`, { convention });
        }
      } catch (err) {
        error('Failed to add meta item', err);
        process.exit(1);
      }
    });

  // kspec meta set <ref>
  meta
    .command('set <ref>')
    .description('Update a meta item')
    .option('--name <name>', 'Update name (agents)')
    .option('--description <description>', 'Update description')
    .option('--capabilities <caps>', 'Replace capabilities (agents, comma-separated)')
    .option('--add-capability <cap>', 'Add capability (agents)')
    .option('--trigger <trigger>', 'Update trigger (workflows)')
    .option('--add-step <step>', 'Add workflow step (format: type:content)')
    .option('--add-rule <rule>', 'Add convention rule')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const item = findMetaItemByRef(metaCtx, ref);

        if (!item) {
          error(`Meta item not found: ${ref}`);
          process.exit(3);
        }

        const itemType = getMetaItemType(item);

        if (itemType === 'agent') {
          const agent = item as LoadedAgent;
          if (options.name) agent.name = options.name;
          if (options.description) agent.description = options.description;
          if (options.capabilities) {
            agent.capabilities = options.capabilities.split(',').map((c: string) => c.trim());
          }
          if (options.addCapability) {
            if (!agent.capabilities.includes(options.addCapability)) {
              agent.capabilities.push(options.addCapability);
            }
          }
          await saveMetaItem(ctx, agent, 'agent');
          await commitIfShadow(ctx.shadow, 'meta-set-agent', shortUlid(agent._ulid));
          success(`Updated agent: ${shortUlid(agent._ulid)}`, { agent });
        } else if (itemType === 'workflow') {
          const workflow = item as LoadedWorkflow;
          if (options.description) workflow.description = options.description;
          if (options.trigger) workflow.trigger = options.trigger;
          if (options.addStep) {
            const [stepType, ...contentParts] = options.addStep.split(':');
            const content = contentParts.join(':');
            if (!['check', 'action', 'decision'].includes(stepType)) {
              error(`Invalid step type: ${stepType}. Valid types: check, action, decision`);
              process.exit(2);
            }
            workflow.steps.push({
              type: stepType as 'check' | 'action' | 'decision',
              content: content || 'New step',
            });
          }
          await saveMetaItem(ctx, workflow, 'workflow');
          await commitIfShadow(ctx.shadow, 'meta-set-workflow', shortUlid(workflow._ulid));
          success(`Updated workflow: ${shortUlid(workflow._ulid)}`, { workflow });
        } else if (itemType === 'convention') {
          const conv = item as LoadedConvention;
          if (options.addRule) {
            conv.rules.push(options.addRule);
          }
          await saveMetaItem(ctx, conv, 'convention');
          await commitIfShadow(ctx.shadow, 'meta-set-convention', shortUlid(conv._ulid));
          success(`Updated convention: ${shortUlid(conv._ulid)}`, { convention: conv });
        } else {
          error('Cannot update observations with meta set. Use meta resolve instead.');
          process.exit(2);
        }
      } catch (err) {
        error('Failed to update meta item', err);
        process.exit(1);
      }
    });

  // kspec meta delete <ref>
  meta
    .command('delete <ref>')
    .description('Delete a meta item')
    .option('--force', 'Skip confirmation prompt')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const metaCtx = await loadMetaContext(ctx);
        const item = findMetaItemByRef(metaCtx, ref);

        if (!item) {
          error(`Meta item not found: ${ref}`);
          process.exit(3);
        }

        const itemType = getMetaItemType(item);
        const itemId = 'id' in item ? item.id : ('domain' in item ? item.domain : shortUlid(item._ulid));

        // Check for references to this item
        const tasks = await loadAllTasks(ctx);
        const referencingTasks = tasks.filter((t) => {
          const metaRef = t.meta_ref;
          if (!metaRef) return false;
          const cleanRef = metaRef.startsWith('@') ? metaRef.slice(1) : metaRef;
          return cleanRef === item._ulid ||
            item._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()) ||
            ('id' in item && item.id === cleanRef) ||
            ('domain' in item && item.domain === cleanRef);
        });

        if (referencingTasks.length > 0 && !options.force) {
          error(`Cannot delete: ${referencingTasks.length} task(s) reference this item. Use --force to override.`);
          process.exit(1);
        }

        // Confirm deletion unless --force
        if (!options.force && !isJsonMode()) {
          const answer = await prompt(`Delete ${itemType} "${itemId}"? (yes/no): `);
          if (answer.toLowerCase() !== 'yes' && answer.toLowerCase() !== 'y') {
            info('Cancelled');
            process.exit(0);
          }
        }

        const deleted = await deleteMetaItem(ctx, item._ulid, itemType);
        if (!deleted) {
          error('Failed to delete meta item');
          process.exit(1);
        }

        await commitIfShadow(ctx.shadow, 'meta-delete', shortUlid(item._ulid));
        success(`Deleted ${itemType}: ${itemId}`, { deleted: true, type: itemType, id: itemId });
      } catch (err) {
        error('Failed to delete meta item', err);
        process.exit(1);
      }
    });

  // kspec meta focus [ref]
  meta
    .command('focus [ref]')
    .description('Get or set session focus')
    .option('--clear', 'Clear current focus')
    .action(async (ref: string | undefined, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const context = await loadSessionContext(ctx);

        if (options.clear) {
          context.focus = null;
          await saveSessionContext(ctx, context);
          success('Cleared focus', { focus: null });
        } else if (ref) {
          const cleanRef = ref.startsWith('@') ? ref : `@${ref}`;
          context.focus = cleanRef;
          await saveSessionContext(ctx, context);
          success(`Set focus: ${cleanRef}`, { focus: cleanRef });
        } else {
          if (context.focus) {
            output({ focus: context.focus }, () => {
              console.log(`Focus: ${chalk.cyan(context.focus)}`);
            });
          } else {
            output({ focus: null }, () => {
              console.log(chalk.gray('No focus set'));
            });
          }
        }
      } catch (err) {
        error('Failed to manage focus', err);
        process.exit(1);
      }
    });

  // kspec meta thread <action> [text]
  meta
    .command('thread <action> [text]')
    .description('Manage active threads (add, remove, list, clear)')
    .action(async (action: string, text: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const context = await loadSessionContext(ctx);

        switch (action) {
          case 'add':
            if (!text) {
              error('Thread text is required');
              process.exit(2);
            }
            context.threads.push(text);
            await saveSessionContext(ctx, context);
            success(`Added thread: "${text}"`, { threads: context.threads });
            break;
          case 'remove': {
            if (!text) {
              error('Thread index is required');
              process.exit(2);
            }
            const index = parseInt(text, 10) - 1; // 1-indexed for user
            if (isNaN(index) || index < 0 || index >= context.threads.length) {
              error(`Invalid thread index: ${text}`);
              process.exit(2);
            }
            const removed = context.threads.splice(index, 1)[0];
            await saveSessionContext(ctx, context);
            success(`Removed thread: "${removed}"`, { threads: context.threads });
            break;
          }
          case 'list':
            output({ threads: context.threads }, () => {
              if (context.threads.length === 0) {
                console.log(chalk.gray('No active threads'));
              } else {
                console.log(chalk.bold('Active Threads:'));
                for (let i = 0; i < context.threads.length; i++) {
                  console.log(`  ${i + 1}. ${context.threads[i]}`);
                }
              }
            });
            break;
          case 'clear':
            context.threads = [];
            await saveSessionContext(ctx, context);
            success('Cleared all threads', { threads: [] });
            break;
          default:
            error(`Invalid action: ${action}. Valid actions: add, remove, list, clear`);
            process.exit(2);
        }
      } catch (err) {
        error('Failed to manage threads', err);
        process.exit(1);
      }
    });

  // kspec meta question <action> [text]
  meta
    .command('question <action> [text]')
    .description('Manage open questions (add, remove, list, clear)')
    .action(async (action: string, text: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        const context = await loadSessionContext(ctx);

        switch (action) {
          case 'add':
            if (!text) {
              error('Question text is required');
              process.exit(2);
            }
            context.open_questions.push(text);
            await saveSessionContext(ctx, context);
            success(`Added question: "${text}"`, { open_questions: context.open_questions });
            break;
          case 'remove': {
            if (!text) {
              error('Question index is required');
              process.exit(2);
            }
            const index = parseInt(text, 10) - 1; // 1-indexed for user
            if (isNaN(index) || index < 0 || index >= context.open_questions.length) {
              error(`Invalid question index: ${text}`);
              process.exit(2);
            }
            const removed = context.open_questions.splice(index, 1)[0];
            await saveSessionContext(ctx, context);
            success(`Removed question: "${removed}"`, { open_questions: context.open_questions });
            break;
          }
          case 'list':
            output({ open_questions: context.open_questions }, () => {
              if (context.open_questions.length === 0) {
                console.log(chalk.gray('No open questions'));
              } else {
                console.log(chalk.bold('Open Questions:'));
                for (let i = 0; i < context.open_questions.length; i++) {
                  console.log(`  ${i + 1}. ${context.open_questions[i]}`);
                }
              }
            });
            break;
          case 'clear':
            context.open_questions = [];
            await saveSessionContext(ctx, context);
            success('Cleared all questions', { open_questions: [] });
            break;
          default:
            error(`Invalid action: ${action}. Valid actions: add, remove, list, clear`);
            process.exit(2);
        }
      } catch (err) {
        error('Failed to manage questions', err);
        process.exit(1);
      }
    });

  // kspec meta context
  meta
    .command('context')
    .description('Show full session context')
    .option('--clear', 'Clear all context')
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error('No kspec project found');
          process.exit(1);
        }

        if (options.clear) {
          const emptyContext: SessionContext = {
            focus: null,
            threads: [],
            open_questions: [],
            updated_at: new Date().toISOString(),
          };
          await saveSessionContext(ctx, emptyContext);
          success('Cleared session context', { context: emptyContext });
        } else {
          const context = await loadSessionContext(ctx);
          output(context, () => formatSessionContext(context));
        }
      } catch (err) {
        error('Failed to manage context', err);
        process.exit(1);
      }
    });
}

